(2, 2, 'Research Colloquium on Sustainable Tourism', 'Presentation of student and faculty research outputs on sustainable and community-based tourism.', 'AVR 2, College of Business and Tourism', DATE_SUB(CURDATE(), INTERVAL 3 DAY) + INTERVAL 13 HOUR, DATE_SUB(CURDATE(), INTERVAL 3 DAY) + INTERVAL 17 HOUR, DATE_SUB(NOW(), INTERVAL 28 DAY), DATE_SUB(CURDATE(), INTERVAL 4 DAY) + INTERVAL 17 HOUR, 120, 1, 1, 0, 'Whole Session', 1, 0, 0, 1, DATE_SUB(NOW(), INTERVAL 29 DAY)),
(3, 1, 'Student Leadership Summit 2025', 'Annual leadership training for student organization officers.', 'Convention Hall', DATE_SUB(CURDATE(), INTERVAL 200 DAY) + INTERVAL 8 HOUR, NULL, NULL, NULL, NULL, 1, 0, 0, 'Whole Day', 1, 0, 1, 1, DATE_SUB(NOW(), INTERVAL 230 DAY));
